 cs=[]
 for z in re.split(r'### Choice ',q)[1:]:
  ps=[r'- Depth: (\d+)',r'Residual connections: (True|False)',r'- Activation: (\w+)',r'- Optimizer: (\w+)',r'- Learning rate: ([\d.e-]+)']
  ms=[re.search(p,z) for p in ps]
  if all(ms):cs.append({'letter':z[0],'depth':int(ms[0][1]),'res':ms[1][1]=='True','smooth':ms[2][1] in ['silu','gelu'],'op':ms[3][1],'lr':float(ms[4][1])})
 order=re.findall(r'[A-E]',r['answer'])
 if len(order)<2:continue
 H.append((r['question_id'],int(t[1]),cs,order))
for name in ['shallow_res_vs_deep_res','plain_smooth_vs_deep_res','smooth_vs_rectifier']:
 for band in ['short','long']:
  hits=[];miss=[]
  for id,t,cs,order in H:
   if (t>=1024)!=(band=='long'):continue
   for a,b in itertools.permutations(cs,2):
    if a['op']!=b['op'] or a['lr']!=b['lr'] or a['op'] not in ['Adam','AdamW','RMSprop'] or a['lr']*t<.05:continue
